/** * @brief Retrieves the resident set size memory usage of the current process on Linux systems.
 *
 * This function reads the `/proc/self/statm` file to obtain memory statistics,
 * calculates the resident set size (RSS) in kilobytes, and returns it.
 *
 * @return The RSS memory usage in kilobytes.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
static double memusage_linux_resident() {
    int tSize = 0, resident = 0, share = 0;
    ifstream buffer("/proc/self/statm");
    buffer >> tSize >> resident >> share;
    buffer.close();

    long page_size_kb = sysconf(_SC_PAGE_SIZE) / 1024; // in case x86-64 is configured to use 2MB pages
    double rss = resident * page_size_kb;
    return rss;
}

/** * @brief Calculates the shared memory usage of the current process on Linux systems.
 *
 * This function reads the `/proc/self/statm` file to obtain memory statistics,
 * specifically the amount of shared memory used by the process. It then converts
 * the shared memory size from pages to kilobytes using the system's page size.
 *
 * @return The shared memory usage in kilobytes.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
static double memusage_linux_shared() {
    int tSize = 0, resident = 0, share = 0;
    ifstream buffer("/proc/self/statm");
    buffer >> tSize >> resident >> share;
    buffer.close();

    long page_size_kb = sysconf(_SC_PAGE_SIZE) / 1024; // in case x86-64 is configured to use 2MB pages
    double shm = share * page_size_kb;
    return shm;
}

/** * @brief Retrieves the total memory usage of the process in kilobytes.
 *
 * Reads the virtual memory size from the /proc/self/statm file,
 * calculates the total memory usage considering the page size,
 * and returns the result in kilobytes.
 *
 * @return The total memory usage of the process in kilobytes.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
static double memusage_linux_size() {
    int tSize = 0, resident = 0, share = 0;
    ifstream buffer("/proc/self/statm");
    buffer >> tSize >> resident >> share;
    buffer.close();

    long page_size_kb = sysconf(_SC_PAGE_SIZE) / 1024; // in case x86-64 is configured to use 2MB pages
    double siz = tSize * page_size_kb;
    return siz;
}


/** * @brief Retrieves the resident memory usage of the process.
 *
 * This function returns the amount of physical memory currently used by the process.
 * On Linux systems, it utilizes the `memusage_linux_resident` function to obtain this information.
 * If called on a non-Linux platform, it returns -1 indicating that the functionality is unsupported.
 *
 * @return double The resident memory usage in bytes, or -1 if unsupported.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
double WCP::memusage_resident() {
#ifdef __linux__
    return memusage_linux_resident();
#endif
    return -1;
}

/** * @brief Retrieves the shared memory usage of the current process on Linux systems.
 *
 * This function returns the amount of shared memory used by the current process,
 * measured in kilobytes (KB).
 *
 * @return double The shared memory usage in KB, or -1 if the platform is not Linux.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
double WCP::memusage_shared()
{
#ifdef __linux__
    return memusage_linux_shared();
#endif
    return -1;
}
/** * @brief Retrieves the memory usage size of the application.
 *
 * On Linux systems, this function returns the memory usage size by calling
 * memusage_linux_size(). If the platform is not Linux, it returns -1.
 *
 * @return double Memory usage size in bytes, or -1 if unsupported platform.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
double WCP::memusage_size()
{
#ifdef __linux__
    return memusage_linux_size();
#endif
    return -1;
}


