/** * @brief Retrieves the current memory usage statistics.
 *
 * This function returns the current memory usage details including both the size and resident set size.
 *
 * @return memusage An object containing the current memory usage information.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
MemUsage::memusage MemUsage::current() const
{
    return memusage(memusage_size(), memusage_resident());
}
/** * @brief Pushes memory usage information along with a message onto the events list.
 *
 * If both components of the memory usage tuple are negative, the current memory usage is retrieved instead.
 *
 * @param msg Message associated with the memory usage entry.
 * @param mu Memory usage tuple containing virtual and resident set size.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
void MemUsage::push(const std::string& msg, MemUsage::memusage mu)
{
    if (mu.first < 0 && mu.second < 0) {
	mu = current();
    }
    m_events.push_back(event(mu,msg));
}

/** * @brief Pushes memory usage information onto the stack and returns a formatted string representation.
 *
 * @param msg Message associated with the memory usage entry.
 * @param mu Memory usage details to be recorded.
 * @return Formatted string summarizing all memory usage entries up to this point.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
std::string MemUsage::operator()(std::string msg, MemUsage::memusage mu)
{
    push(msg, mu);
    return emit(-1);
}

	/// Return event by index.
MemUsage::event MemUsage::operator[](int ind) const
{
    while (ind < 0) { ind += m_events.size();}

    return m_events[ind];
}

/** * @brief Generates a summary of memory usage events.
 *
 * Iterates through the stored memory usage events and appends the result of emit() for each event to a string stream.
 * Returns the concatenated string containing summaries of all memory usage events.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
std::string MemUsage::summary() const
{
    stringstream ss;
    for (int ind=0; ind<m_events.size(); ++ind) {
	ss << this->emit(ind) << "\n";
    }
    return ss.str();
}

/** * @brief Emits memory usage statistics for a specified event index relative to previous events.
 *
 * This function calculates and formats the memory usage difference between the current event
 * and the previous event, along with the total memory usage for the current event.
 *
 * @param ind Index of the event for which memory usage statistics are emitted.
 *            Negative indices wrap around to positive indices starting from the end of the event list.
 * @return Formatted string containing memory usage statistics including total and incremental values.
 * This comment was generated by Qwen/Qwen2.5-Coder-32B-Instruct:None at temperature 0.01.
*/ 
std::string MemUsage::emit(int ind) const
{
    while (ind < 0) { ind += m_events.size();}
    int prev_ind = ind-1;
    if (prev_ind<0) prev_ind=0;

    const memusage& prev_mem = (*this)[prev_ind].first;
    const memusage& evt_mem = (*this)[ind].first;
    const string& evt_msg = (*this)[ind].second;

    memusage from_prev(evt_mem.first - prev_mem.first, evt_mem.second - prev_mem.second);

    stringstream ss;
    ss << "MEM: total: size=" << evt_mem.first << "K, res=" << evt_mem.second << "K "
       << "increment: size=" << from_prev.first << "K, res=" << from_prev.second << "K "
       << evt_msg;
    return ss.str();
}
